ALTER TABLE "Recipe" ADD COLUMN "isShared" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "Ingredient" ADD COLUMN "emoji" TEXT;
ALTER TABLE "Profile" ADD COLUMN "coverUrl" TEXT;
ALTER TABLE "Profile" ADD COLUMN "showRecipes" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "Category" ("name" TEXT NOT NULL PRIMARY KEY);
INSERT INTO "Category" ("name") SELECT DISTINCT "category" FROM "Ingredient";
CREATE TABLE "Comment" ("id" TEXT NOT NULL PRIMARY KEY,"text" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"userId" TEXT NOT NULL,"recipeId" TEXT NOT NULL, FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("recipeId") REFERENCES "Recipe"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "Comment_recipeId_createdAt_idx" ON "Comment"("recipeId","createdAt");
CREATE TABLE "Rating" ("userId" TEXT NOT NULL,"recipeId" TEXT NOT NULL,"value" INTEGER NOT NULL CHECK ("value" BETWEEN 1 AND 5), PRIMARY KEY ("userId","recipeId"), FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY ("recipeId") REFERENCES "Recipe"("id") ON DELETE CASCADE ON UPDATE CASCADE);
